require "action_dispatch/middleware/session/abstract_store"

module ActionDispatch
  module Session
    # Stores the Rails session hash in the browser_sessions table.
    #
    # Follows Rails' server-side session pattern (as generated by
    # `rails g authentication`): the browser holds only an unguessable random
    # id, the row is found by a SHA-256 of it (so a database leak cannot be
    # replayed as a cookie), the session is resolved once per request and
    # logging out or `reset_session` deletes the row. A signed cookie is not
    # added: the id is already a 128 bit random bearer token, and re-signing it
    # would log out everyone with an existing cookie.
    #
    # Replaces the former Redis-backed CacheStore without changing its
    # semantics: expiry is `expire_after` from the last write (not refreshed by
    # requests that don't load the session), and expired rows are ignored on
    # read whether or not cleanup has removed them.
    #
    # TRANSITION: a request whose id is not in the database falls back to the
    # old cache entry. Its contents are written to the database when the
    # request ends and the cache entry is then deleted. Remove the legacy_*
    # methods once `expire_after` has passed since deploying.
    class DatabaseStore < AbstractSecureStore
      LOADED_FROM = "action_dispatch.session.database_store.loaded_from".freeze

      def find_session(req, sid)
        if sid && (found = find_in_database(sid))
          req.set_header(LOADED_FROM, [:database, sid.private_id])
          [sid, found]
        elsif sid && (legacy = find_legacy(sid))
          req.set_header(LOADED_FROM, [:legacy, sid.private_id])
          [sid, legacy]
        else
          [generate_sid, {}]
        end
      end

      def write_session(req, sid, session, options)
        private_id = sid.private_id
        source, loaded_id = req.get_header(LOADED_FROM)
        loaded = loaded_id == private_id ? source : nil

        if session.blank?
          delete_everywhere(sid)
        elsif loaded == :database
          # Updating rather than inserting means a row deleted by another
          # request (e.g. logout) is not resurrected by this one.
          return false unless update_row(private_id, session, options)
        elsif loaded == :legacy
          return false unless legacy_present?(sid)

          upsert_row(private_id, session, options)
          delete_legacy(sid)
        else
          upsert_row(private_id, session, options)
        end

        sid
      end

      def delete_session(_req, sid, options)
        delete_everywhere(sid)
        generate_sid unless options[:drop]
      end

    private

      def find_in_database(sid)
        row = BrowserSession.live.find_by(session_id: sid.private_id)
        row&.payload
      end

      def update_row(private_id, session, options)
        BrowserSession.live.where(session_id: private_id).update_all(
          session_data: BrowserSession.dump(session),
          expires_at: expiry(options),
          updated_at: Time.current
        ).positive?
      end

      def upsert_row(private_id, session, options)
        BrowserSession.upsert(
          {
            session_id: private_id,
            session_data: BrowserSession.dump(session),
            expires_at: expiry(options)
          },
          unique_by: :session_id
        )
      end

      def expiry(options)
        options[:expire_after].seconds.from_now
      end

      def delete_everywhere(sid)
        BrowserSession.where(session_id: sid.private_id).delete_all
        delete_legacy(sid)
      end

      def legacy_key(id)
        "_session_id:#{id}"
      end

      def find_legacy(sid)
        Rails.cache.read(legacy_key(sid.private_id)) ||
          Rails.cache.read(legacy_key(sid.public_id))
      end

      def legacy_present?(sid)
        Rails.cache.exist?(legacy_key(sid.private_id)) ||
          Rails.cache.exist?(legacy_key(sid.public_id))
      end

      def delete_legacy(sid)
        Rails.cache.delete(legacy_key(sid.private_id))
        Rails.cache.delete(legacy_key(sid.public_id))
      end
    end
  end
end
